        <rule id="_lineDiscount_rule_1">
          <inputEntry id="_lineDiscount_rule_1_in_1"><text>"Books"</text></inputEntry>
          <inputEntry id="_lineDiscount_rule_1_in_2"><text>-</text></inputEntry>
          <inputEntry id="_lineDiscount_rule_1_in_3"><text>-</text></inputEntry>
          <inputEntry id="_lineDiscount_rule_1_in_4"><text>"DE", "AT"</text></inputEntry>
          <outputEntry id="_lineDiscount_rule_1_out_1"><text>0</text></outputEntry>
          <outputEntry id="_lineDiscount_rule_1_out_2"><text>"Fixed book price in DE and AT: no discount"</text></outputEntry>
        </rule>
